function widget(kind) {

  if(kind==='qualivision') return `<div class="interactive"><div class="widget-head"><span class="eyebrow">CONNECT → COMPARE → REFLECT</span><span class="demo-label">Fictional example</span></div><div class="choice-row" role="group" aria-label="Qualitative analysis stage"><button data-qv-stage="evidence" aria-pressed="true">Timeline links</button><button data-qv-stage="codes" aria-pressed="false">Trace + compare</button><button data-qv-stage="reflection" aria-pressed="false">AI-assisted reflection</button></div><div class="qv-demo-panel" aria-live="polite"></div><p class="widget-caption">A fictional walkthrough of the design goals: linked evidence, evolving coding relationships, and AI-assisted reflection.</p></div>`;
  if(kind==='charles') return `<div class="interactive"><div class="widget-head"><span class="eyebrow">CHOOSE THE EXPLANATION DETAIL</span><span class="demo-label">Synthetic data</span></div><div class="change-example"><div><span>Group A</span><b>10 → 30</b></div><div><span>Group B</span><b>20 → 25</b></div><div><span>Group C</span><b>30 → 30</b></div></div><div class="choice-row" role="group" aria-label="Explanation detail"><button data-change-detail="concise" aria-pressed="true">Concise summary</button><button data-change-detail="detailed" aria-pressed="false">Detailed summary</button></div><div class="change-demo-panel" aria-live="polite"></div><p class="widget-caption">Compare a broad statement with group-specific changes in this illustrative example.</p></div>`;
  if(kind==='bib-study') return `<figure class="case-research-flow flow-lavender" aria-labelledby="bib-flow-title"><figcaption id="bib-flow-title"><strong>From comparison to everyday use</strong><span>21 experts · Two phases</span></figcaption><ol><li><span class="case-flow-number">01</span><div><h3>Moderated remote study + interview</h3><p>Clean provided bibliography files with BibWrangler and the usual workflow in Overleaf while thinking aloud, then discuss the experience in a post-task interview.</p></div></li><li><span class="case-flow-number">02</span><div><h3>Two-week take-home study</h3><p>Use BibWrangler in their own projects, then report their experience in a questionnaire.</p></div></li></ol><div class="case-flow-conclusion"><h3>Thematic analysis</h3><p>Connect structured-task experiences with workflow fit in everyday writing.</p></div></figure>`;
  if(kind==='palette-study') return `<figure class="case-research-flow flow-yellow" aria-labelledby="palette-flow-title"><figcaption id="palette-flow-title"><strong>Study workflow</strong><span>40 designers · One tool per participant</span></figcaption><ol><li><span class="case-flow-number">01</span><div><h3>One assigned palette tool</h3><div class="case-flow-chips"><a href="https://color-buddy.netlify.app/" target="_blank" rel="noopener">Color Buddy ↗</a><a href="https://qualpal.cc" target="_blank" rel="noopener">QualPal ↗</a><a href="https://www.susielu.com/data-viz/viz-palette" target="_blank" rel="noopener">Viz Palette ↗</a><a href="https://colorexplorer.com/" target="_blank" rel="noopener">ColorExplorer ↗</a></div></div></li><li><span class="case-flow-number">02</span><div><h3>Design under different constraints</h3><p>Accessibility: CVD-friendly or contrast-focused<br>Thematic: specified brand colors<br>Freestyle: personal aesthetic preference</p></div></li><li><span class="case-flow-number">03</span><div><h3>Compare the process and the palettes</h3><p>Code screen and think-aloud recordings; examine task time, contrast, and color distinguishability.</p></div></li></ol></figure>`;
  if(kind==='charles-algorithm') return `<figure class="case-research-flow flow-sand" aria-labelledby="charles-algorithm-title"><figcaption id="charles-algorithm-title"><strong>Change-summary discovery pipeline</strong><span>Setup assistant + Discovery engine</span></figcaption><ol><li><span class="case-flow-number">01</span><div><h3>Search attribute combinations</h3><p>Use correlation to suggest attributes, then enumerate condition and transformation subsets within the chosen size limits.</p></div></li><li><span class="case-flow-number">02</span><div><h3>Discover data partitions</h3><p>Fit an initial regression model, then use distances from that model to guide k-means partition discovery.</p></div></li><li><span class="case-flow-number">03</span><div><h3>Fit transformations within each partition</h3><p>Refit a linear model within each partition and pair it with the partition’s condition.</p></div></li><li><span class="case-flow-number">04</span><div><h3>Score and rank candidate summaries</h3><p>Rank sets of conditional transformations by their accuracy and interpretability.</p></div></li></ol><div class="case-flow-conclusion charles-score"><code>Score = α × Accuracy + (1 − α) × Interpretability</code><p>Accuracy compares transformed source values with target values. Interpretability favors compact summaries, simple rules, broad coverage, and readable constants.</p></div></figure>`;
  if(kind==='charles-output') return `<figure class="charles-rule-example" aria-labelledby="charles-rule-title"><figcaption id="charles-rule-title"><strong>Example conditional transformation</strong><span>Employee-bonus example</span></figcaption><div class="charles-rule-grid"><div><span>CONDITION</span><code>education = PhD</code><p>Which records?</p></div><span class="charles-rule-arrow" aria-hidden="true">→</span><div><span>TRANSFORMATION</span><code>new_bonus = 1.05 × old_bonus + 1000</code><p>How did their values change?</p></div></div></figure>`;
  if(kind==='dsf-study') return `<figure class="study-flow dsf-study-flow" aria-labelledby="dsf-flow-title"><figcaption id="dsf-flow-title"><strong>Two complementary studies</strong><span>Task performance + everyday practice</span></figcaption><div class="dsf-study-paths"><section class="dsf-study-path" aria-label="Controlled usability study"><div class="dsf-study-start"><span class="study-flow-label">USABILITY STUDY</span><h3><b>215</b> crowd workers</h3><p class="dsf-recruitment">No prior programming experience required</p></div><ol><li><h4>One format + one context</h4><p>7 formats · Tabular or configuration data</p><div class="dsf-study-formats"><span>JSON</span><span>JSONC</span><span>JSON5</span><span>HJSON</span><span>YAML</span><span>TOML</span><span>XML</span></div></li><li><h4>Tutorial + practice</h4></li><li><h4>Read, author, and modify data</h4></li><li><h4>Compare performance and effort</h4><p>Task scores · Completion time · Perceived difficulty</p></li></ol></section><section class="dsf-study-path" aria-label="Practitioner interview study"><div class="dsf-study-start"><span class="study-flow-label">PRACTITIONER INTERVIEWS</span><h3><b>9</b> developers</h3></div><ol><li><h4>Experienced practitioners</h4><p>At least 3 years of relevant experience</p></li><li><h4>Semi-structured interviews</h4><p>Format choices, editing, and maintenance in their own work</p></li><li><h4>Affinity diagramming</h4><p>Group interview accounts into recurring themes</p></li></ol></section></div><div class="dsf-study-merge" aria-hidden="true"><span></span></div><div class="study-flow-analysis"><h3>Connect the two perspectives</h3><p>What notation changes in a task, and what supports usability in practice</p></div></figure>`;
  if(kind==='dsf') return `<div class="interactive"><div class="widget-head"><span class="eyebrow">EXPLORE THE NOTATION</span><span class="demo-label">Illustrative example</span></div><div class="choice-row" data-format-tabs role="group" aria-label="Data format"><button data-format="json" aria-pressed="true">JSON</button><button data-format="yaml" aria-pressed="false">YAML</button><button data-format="xml" aria-pressed="false">XML</button></div><pre class="format-output" aria-live="polite"></pre><p class="widget-caption">The same information in three formats: compare how each represents lists and nested values.</p></div>`;
  if(kind==='wrangling-study') return `<figure class="study-flow" aria-labelledby="wrangling-flow-title"><figcaption id="wrangling-flow-title"><strong>Study workflow</strong><span>Between-subjects · One tool per participant</span></figcaption><ol class="study-flow-pipeline"><li class="study-flow-node"><span class="study-flow-label">PARTICIPANTS</span><h3><b class="study-flow-count">40</b> freelancers</h3><p>Remote study</p></li><li class="study-flow-node"><span class="study-flow-label">TOOL ASSIGNMENT</span><h3>One assigned tool</h3><div class="study-flow-tools"><span><span class="study-flow-tool-icon" aria-hidden="true"><img class="study-flow-logo-excel" src="assets/tools/excel.svg" alt=""></span>Excel</span><span><span class="study-flow-tool-icon" aria-hidden="true"><img class="study-flow-logo-jupyter" src="assets/tools/jupyter.svg" alt=""></span>Jupyter</span><span><span class="study-flow-tool-icon" aria-hidden="true"><img class="study-flow-logo-chatgpt" src="assets/ai/chatgpt.svg" alt=""></span>ChatGPT</span><span><span class="study-flow-tool-icon" aria-hidden="true"><img class="study-flow-logo-openrefine" src="assets/tools/openrefine.svg" alt=""></span>OpenRefine</span></div></li><li class="study-flow-node"><span class="study-flow-label">TASKS</span><h3>Two data-cleaning tasks</h3><p>Complete both tasks with the assigned tool</p></li></ol><div class="study-flow-connector study-flow-branch" aria-hidden="true"><svg class="study-flow-wide" viewBox="0 0 600 44" preserveAspectRatio="none"><path d="M518 0V15H100V35 M300 15V35 M518 15V26H500V35"/><path class="flow-arrowhead" d="m96 30 4 5 4-5 M296 30l4 5 4-5 M496 30l4 5 4-5"/></svg><span class="study-flow-narrow">↓</span></div><div class="study-flow-label study-flow-evidence-label">EVIDENCE COLLECTED</div><div class="study-flow-evidence"><div><h3>Process</h3><p>Screen recordings<br>Think-aloud recordings</p></div><div><h3>Output</h3><p>Cleaned datasets</p></div><div><h3>Experience</h3><p>Workload questionnaires<br>Usability questionnaires</p></div></div><div class="study-flow-connector study-flow-merge" aria-hidden="true"><svg class="study-flow-wide" viewBox="0 0 600 44" preserveAspectRatio="none"><path d="M100 0V14H300V35 M300 0V35 M500 0V14H300"/><path class="flow-arrowhead" d="m296 30 4 5 4-5"/></svg><span class="study-flow-narrow">↓</span></div><div class="study-flow-analysis"><h3>Mixed-methods analysis</h3><p>Connect cleaning strategies with output quality and user experience</p></div></figure>`;
  if(kind==='wrangling') return `<div class="interactive"><div class="widget-head"><span class="eyebrow">EXPLORE THE STRATEGY DIFFERENCE</span><span class="demo-label">Conceptual illustration</span></div><div class="choice-row" role="group" aria-label="Workflow lens"><button data-lens="data" aria-pressed="true">Start with visible data</button><button data-lens="abstract" aria-pressed="false">Start with a transformation</button></div><div class="lens-panel" aria-live="polite"></div></div>`;
  if(kind==='bib') return `<div class="interactive"><div class="widget-head"><span class="eyebrow">FROM THEME TO OPPORTUNITY</span><span class="demo-label">Portfolio synthesis</span></div><div class="evidence-chain"><span>Reviewable changes</span><b aria-hidden="true">→</b><span>Confidence in repair</span><b aria-hidden="true">→</b><span>Before / after inspection</span></div><p class="widget-caption">A traceable design rationale: a coded theme → the user need it suggests → a feature to evaluate.</p></div>`;
  return `<div class="interactive"><div class="widget-head"><span class="eyebrow">TRY A DIFFERENT CONTEXT</span><span class="demo-label">Synthetic palette</span></div><div class="choice-row" role="group" aria-label="Palette background"><button data-background="light" aria-pressed="true">Light background</button><button data-background="dark" aria-pressed="false">Dark background</button></div><div class="palette-preview"><div class="chart-bars" aria-label="Illustrative bars using five colors"><i style="--h:45%;--c:#d6764f"></i><i style="--h:82%;--c:#486a62"></i><i style="--h:63%;--c:#a7b8c0"></i><i style="--h:96%;--c:#cca34c"></i><i style="--h:55%;--c:#8e83aa"></i></div><div class="swatches"><span>#D6764F</span><span>#486A62</span><span>#A7B8C0</span><span>#CCA34C</span><span>#8E83AA</span></div></div><p class="widget-caption">Compare how the same colors appear on light and dark backgrounds.</p></div>`;
}

function renderProject(id) {
  const p=projects.find(x=>x.id===id);
  if(!p){renderHome('work');return;}
  currentProject=p; isDeck=false;deckIndex=0;
  document.title=p.short+' — Shiyi He';
  document.body.dataset.page='project';
  setSiteNavigation('home');
  main.innerHTML=`<div class="case-top wrap"><a class="back-link" href="#work">← All research</a><div class="case-top-right"><span>${p.time} read</span><button class="mode-button" aria-pressed="false">Guided view <span aria-hidden="true">▣</span></button></div></div><section class="case-hero wrap" data-project="${p.id}"><div class="eyebrow">${p.number} / ${p.category} <span class="venue">${p.venue}</span></div><h1>${p.title}</h1><p class="case-intro">${p.intro}</p>${p.showFacts===false?'':`<div class="case-facts"><div><span>${p.questionLabel||'RESEARCH QUESTION'}</span><p>${p.question}</p></div><div><span>${p.factLabel||'STUDY'}</span><p>${p.stat}</p></div><div><span>METHODS</span><p>${p.methods.join(' · ')}</p></div></div>`}${p.takeaway?`<div class="takeaway"><span>THE TAKEAWAY</span><p>${p.takeaway}</p></div>`:""}</section><div class="case-layout wrap"><aside class="case-outline"><div class="eyebrow">IN THIS CASE</div><nav aria-label="Case study sections">${p.sections.map((s,i)=>`<a href="#project/${p.id}/${s.id}" data-section="${s.id}"><span>0${i+1}</span>${s.label}</a>`).join('')}</nav><a class="outline-paper" href="${p.links[0][1]}" target="_blank" rel="noopener">${p.links[0][0]} ${arrow}</a></aside><div class="case-body"><div class="deck-bar" hidden><span class="deck-count"></span><div><button data-deck="prev" aria-label="Previous section">←</button><button data-deck="next" aria-label="Next section">→</button></div></div>${p.sections.map((s,i)=>`<section class="case-section" id="section-${s.id}" data-idx="${i}"><div class="eyebrow">0${i+1} / ${s.label.toUpperCase()}</div><h2>${s.title}</h2><p>${s.body}</p>${s.figure?`<figure class="case-paper-figure"><button class="paper-figure-image" data-open-paper-figure aria-label="Enlarge figure"><img src="${s.figure.src}" width="${s.figure.width}" height="${s.figure.height}" alt="${s.figure.alt}" loading="lazy"></button><figcaption><div>${s.figure.caption?`<span>${s.figure.caption}</span>`:''}<a href="${s.figure.sourceUrl}" target="_blank" rel="noopener">${s.figure.sourceLabel} ↗</a></div><button class="paper-figure-expand" data-open-paper-figure>View full size <span aria-hidden="true">↗</span></button></figcaption><dialog class="paper-figure-dialog" style="--paper-figure-original-width:${s.figure.width}px" aria-label="${p.short}: ${s.figure.title||s.figure.caption}"><div class="paper-figure-toolbar"><span>${p.short} · ${s.figure.title||'System architecture'}</span><div><button data-zoom-paper-figure aria-pressed="false">Original size</button><button data-close-paper-figure aria-label="Close figure">Close ×</button></div></div><div class="paper-figure-scroll"><img src="${s.figure.src}" width="${s.figure.width}" height="${s.figure.height}" alt="${s.figure.alt}"></div></dialog></figure>`:''}${s.designContribution?`<aside class="design-contribution" aria-label="Core design contribution"><span class="eyebrow">${s.designContribution.label}</span><h3>${s.designContribution.title}</h3><p>${s.designContribution.body}</p><p class="contribution-rationale">${s.designContribution.rationale}</p></aside>`:''}${s.callout?`<blockquote>${s.callout}</blockquote>`:''}${s.steps?`<ol class="study-steps">${s.steps.map((x,j)=>`<li><span>0${j+1}</span>${x}</li>`).join('')}</ol>`:''}${s.cards?`<div class="insight-list">${s.cards.map((x,j)=>`<div><span class="insight-num">0${j+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div>`:''}${s.widget?(Array.isArray(s.widget)?s.widget:[s.widget]).map(widget).join(''):''}${s.extra?`<p>${s.extra}</p>`:''}</section>`).join('')}<section class="case-resources"><div class="eyebrow">GO TO THE SOURCE</div><div class="resource-links">${p.links.map(x=>`<a class="button" href="${x[1]}" target="_blank" rel="noopener">${x[0]} ${arrow}</a>`).join('')}</div></section></div></div><section class="next-case wrap"><span class="eyebrow">KEEP EXPLORING</span><a href="#project/${projects[(projects.indexOf(p)+1)%projects.length].id}">${projects[(projects.indexOf(p)+1)%projects.length].short} <span>↗</span></a></section>`;
  bindWidgets();
  document.querySelector('.mode-button').addEventListener('click',toggleDeck);
  document.querySelectorAll('[data-deck]').forEach(b=>b.addEventListener('click',()=>{deckIndex+=b.dataset.deck==='next'?1:-1;updateDeck();}));
  window.scrollTo(0,0);
}

const formats={json:'{\n  "study": "data formats",\n  "participants": 215,\n  "methods": ["tasks", "interviews"]\n}',yaml:'study: data formats\nparticipants: 215\nmethods:\n  - tasks\n  - interviews',xml:'<study>\n  <name>data formats</name>\n  <participants>215</participants>\n  <methods>\n    <method>tasks</method>\n    <method>interviews</method>\n  </methods>\n</study>'};
function bindWidgets(){
  const figureDialog=document.querySelector('.paper-figure-dialog');
  if(figureDialog){
    const zoom=document.querySelector('[data-zoom-paper-figure]');
    document.querySelectorAll('[data-open-paper-figure]').forEach(b=>b.addEventListener('click',()=>figureDialog.showModal()));
    document.querySelector('[data-close-paper-figure]').addEventListener('click',()=>figureDialog.close());
    zoom.addEventListener('click',()=>{const actual=figureDialog.classList.toggle('is-original');zoom.setAttribute('aria-pressed',String(actual));zoom.textContent=actual?'Fit to window':'Original size';});
  }


  const qvViews={
    evidence:'<span class="demo-step-label">01 / TIMELINE LINKS</span><h3>Connect a moment with its code and note.</h3><div class="demo-evidence-quote"><span>Fictional clip · 00:42–00:48</span><p>A person pauses, opens a filter menu, then closes it without choosing an option.</p></div><div class="demo-code-options"><div><span>Linked code</span><b>Uncertainty</b></div><div><span>Linked analytic note</span><b>Check what happens next.</b></div></div><p>The evidence, code, and note share a timeline reference. Revisit this moment alongside earlier and later observations.</p>',
    codes:'<span class="demo-step-label">02 / CODING EVOLUTION + COMPARISON</span><h3>Follow how a coding relationship changes.</h3><div class="demo-code-options"><div><span>Earlier code grouping</span><b>Uncertainty → Menu browsing</b></div><div><span>Revised code grouping</span><b>Exploration → Menu browsing</b></div></div><div class="demo-evidence-quote"><span>Revision note · linked to 00:42–00:48</span><p>Moved “Menu browsing” from “Uncertainty” to “Exploration” after reviewing later moments where the person compares other options.</p></div><p>Compare the earlier and revised parent–child relationships between codes while keeping the revision note and linked evidence accessible.</p>',
    reflection:'<span class="demo-step-label">03 / AI-ASSISTED REFLECTION</span><h3>Explore a possible connection, then inspect it.</h3><div class="demo-evidence-quote"><span>Illustrative AI prompt</span><p>Do pauses near menu changes form a pattern across the timeline? Compare moments coded as uncertainty and exploration. Which evidence supports or challenges that relationship?</p></div><p>Visual comparison helps locate relevant moments. The researcher revisits the evidence and notes, then decides whether to develop, revise, or reject the emerging insight.</p>'
  };
  const qvPanel=document.querySelector('.qv-demo-panel');if(qvPanel)qvPanel.innerHTML=qvViews.evidence;
  document.querySelectorAll('[data-qv-stage]').forEach(b=>b.addEventListener('click',()=>{selectButton(b);qvPanel.innerHTML=qvViews[b.dataset.qvStage];}));
  const changeViews={
    concise:'<span class="demo-step-label">ONE BROAD STATEMENT</span><h3>Values increased overall.</h3><p>A short summary conveys the general direction, but hides which groups changed and by how much.</p>',
    detailed:'<span class="demo-step-label">THREE GROUP-SPECIFIC STATEMENTS</span><h3>Different groups, different changes.</h3><ul><li>Group A increased by 20.</li><li>Group B increased by 5.</li><li>Group C stayed unchanged.</li></ul><p>The extra detail preserves variation, while asking the reader to consider more rules.</p>'
  };
  const changePanel=document.querySelector('.change-demo-panel');if(changePanel)changePanel.innerHTML=changeViews.concise;
  document.querySelectorAll('[data-change-detail]').forEach(b=>b.addEventListener('click',()=>{selectButton(b);changePanel.innerHTML=changeViews[b.dataset.changeDetail];}));
  const out=document.querySelector('.format-output');if(out)out.textContent=formats.json;
  document.querySelectorAll('[data-format]').forEach(b=>b.addEventListener('click',()=>{selectButton(b);out.textContent=formats[b.dataset.format];}));
  function lens(type){const panel=document.querySelector('.lens-panel');if(!panel)return; panel.innerHTML=type==='data'?'<span class="lens-large">See → Adjust → Inspect</span><p>Visible data offers a concrete starting point for noticing and acting on local issues.</p>':'<span class="lens-large">Plan → Transform → Evaluate</span><p>Expressing a transformation can support systematic reasoning, while requiring more abstraction.</p>';}
  lens('data');
  document.querySelectorAll('[data-lens]').forEach(b=>b.addEventListener('click',()=>{selectButton(b);lens(b.dataset.lens);}));
  document.querySelectorAll('[data-background]').forEach(b=>b.addEventListener('click',()=>{selectButton(b);document.querySelector('.palette-preview').classList.toggle('dark',b.dataset.background==='dark');}));
}
function selectButton(b){b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}
function toggleDeck(){isDeck=!isDeck;document.querySelector('.mode-button').setAttribute('aria-pressed',String(isDeck));document.querySelector('.mode-button').innerHTML=isDeck?'Continuous view <span aria-hidden="true">☰</span>':'Guided view <span aria-hidden="true">▣</span>';document.querySelector('.deck-bar').hidden=!isDeck;document.querySelector('.case-layout').classList.toggle('is-deck',isDeck);updateDeck();}
function updateDeck(){if(!currentProject)return;deckIndex=Math.max(0,Math.min(currentProject.sections.length-1,deckIndex));document.querySelectorAll('.case-section').forEach((s,i)=>s.hidden=isDeck&&i!==deckIndex);document.querySelector('.deck-count').textContent=`${deckIndex+1} / ${currentProject.sections.length} — ${currentProject.sections[deckIndex].label}`;document.querySelector('[data-deck="prev"]').disabled=deckIndex===0;document.querySelector('[data-deck="next"]').disabled=deckIndex===currentProject.sections.length-1;document.querySelectorAll('[data-section]').forEach((a,i)=>a.classList.toggle('active',isDeck&&i===deckIndex));if(isDeck)document.querySelector('.case-layout').scrollIntoView({block:'start'});}

const siteSections = {"publications": "<section id=\"publications\" class=\"standalone-page publications-page wrap\" aria-labelledby=\"publications-title\">\n            <div class=\"page-intro\"><span class=\"eyebrow\">PAPERS & POSTERS</span><h1 id=\"publications-title\">Publications.</h1><a class=\"text-link scholar-link\" href=\"https://scholar.google.com/citations?user=Fw0t83UAAAAJ&hl=en\" target=\"_blank\" rel=\"noopener noreferrer\"><svg viewBox=\"0 0 24 24\" width=\"21\" height=\"21\" aria-hidden=\"true\"><path d=\"m2 9 10-6 10 6-10 6Z\"/><path d=\"M6 12v6c4 3 8 3 12 0v-6M22 9v9\"/></svg>Google Scholar <span aria-hidden=\"true\">↗</span></a></div>\n\n            <div class=\"publication-groups\"><section class=\"publication-group\" aria-labelledby=\"publication-year-2026\"><h3 class=\"publication-year\" id=\"publication-year-2026\">2026</h3><article class=\"publication\">\n                        <figure class=\"publication-image\">\n                            <img src=\"assets/publications/dsf.jpg\" alt=\"Examples of structured data in different serialization formats\" loading=\"lazy\">\n                        </figure>\n                        <div class=\"pub-main\">\n                            <h4>\n                                <a href=\"https://arxiv.org/abs/2607.26211\" target=\"_blank\" rel=\"noopener noreferrer\">\n                                    Reading Between the Curly Braces: On Textual Data Serialization Format Usability\n                                </a>\n                            </h4>\n                            <p class=\"publication-details\">\n                                <span class=\"authors\"><strong>Shiyi He</strong> ·  Zach Cutler · Andrew McNutt</span>\n                                <span class=\"detail-separator\">—</span>\n                                <em class=\"venue\">IEEE Symposium on Visual Languages and Human Centered Computing (VL/HCC) 2026</em>\n                            </p>\n                        </div>\n                    </article>\n<article class=\"publication\">\n                        <figure class=\"publication-image\">\n                            <img src=\"assets/publications/wrangler.jpg\" alt=\"Comparison of data-wrangling tools\" loading=\"lazy\">\n                        </figure>\n                        <div class=\"pub-main\">\n                            <h4>\n                                <a href=\"https://arxiv.org/abs/2607.26198\" target=\"_blank\" rel=\"noopener noreferrer\">\n                                    How Wrangling Tools Shape Wrangling: A Technical Dimensions Analysis\n                                </a>\n                            </h4>\n                            <p class=\"publication-details\">\n                                <span class=\"authors\"><strong>Shiyi He</strong> ·  El Kindi Rezig · Paul Rosen · Andrew McNutt</span>\n                                <span class=\"detail-separator\">—</span>\n                                <em class=\"venue\">IEEE Symposium on Visual Languages and Human Centered Computing (VL/HCC) 2026</em>\n                            </p>\n                        </div>\n                    </article>\n<article class=\"publication\">\n                        <figure class=\"publication-image publication-image-system\">\n                            <img src=\"assets/publications/qualivision.png\" alt=\"QualiVision workspace connecting video evidence, transcripts, coding, visualization, and AI support\" loading=\"lazy\">\n                        </figure>\n                        <div class=\"pub-main\">\n                            <h4><a href=\"https://arxiv.org/abs/2608.13594\" target=\"_blank\" rel=\"noopener noreferrer\">Towards Scaling Qualitative Analysis of Video Data</a></h4>\n                            <p class=\"publication-details\">\n                                <span class=\"authors\"><strong>Shiyi He</strong></span>\n                                <span class=\"detail-separator\">—</span>\n                                <em class=\"venue\">IEEE Symposium on Visual Languages and Human Centered Computing (VL/HCC), Graduate Consortium, 2026</em>\n                            </p>\n                        </div>\n                    </article>\n<article class=\"publication\">\n                        <figure class=\"publication-image publication-image-icon\">\n                            <img src=\"assets/publications/palette-icon.svg\" alt=\"Color palette illustration\" loading=\"lazy\">\n                        </figure>\n                        <div class=\"pub-main\">\n                            <h4><a href=\"https://arxiv.org/abs/2608.19148\" target=\"_blank\" rel=\"noopener noreferrer\">Trade-offs in Data Color Palette Design Tools</a></h4>\n                            <p class=\"publication-details\">\n                                <span class=\"authors\"><strong>Shiyi He</strong> · Andrew McNutt</span>\n                                <span class=\"detail-separator\">—</span>\n                                <em class=\"venue\">IEEE VIS, Poster, 2026</em>\n                            </p>\n                        </div>\n                    </article></section>\n<section class=\"publication-group\" aria-labelledby=\"publication-year-2025\"><h3 class=\"publication-year\" id=\"publication-year-2025\">2025</h3><article class=\"publication\">\n                        <figure class=\"publication-image\">\n                            <img src=\"assets/publications/charles.jpg\" alt=\"ChARLES change-summary interface\" loading=\"lazy\">\n                        </figure>\n                        <div class=\"pub-main\">\n                            <h4>\n                                <a href=\"https://dl.acm.org/doi/10.1145/3722212.3725089\" target=\"_blank\" rel=\"noopener noreferrer\">\n                                    ChARLES: Change-Aware Recovery of Latent Evolution Semantics in Relational Data\n                                </a>\n                            </h4>\n                            <p class=\"publication-details\">\n                                <span class=\"authors\"><strong>Shiyi He</strong> · Alexandra Meliou · Anna Fariha</span>\n                                <span class=\"detail-separator\">—</span>\n                                <em class=\"venue\">ACM SIGMOD Conference, Demo Track, 2025</em>\n                            </p>\n                        </div>\n                    </article></section></div></section>", "experiences": "<section id=\"experiences\" class=\"standalone-page experiences-page wrap\" aria-labelledby=\"experiences-title\">\n<div class=\"page-intro\"><h1 id=\"experiences-title\">Experiences.</h1><nav class=\"experience-index\" aria-label=\"Experience sections\"><a href=\"experiences/#education\">Education</a><a href=\"experiences/#internships\">Internship</a><a href=\"experiences/#teaching\">Teaching</a><a href=\"experiences/#service\">Service</a></nav></div>\n<div class=\"experience-panels\">\n  <section class=\"experience-panel education-panel\" id=\"education\" aria-labelledby=\"education-title\"><h2 id=\"education-title\">Education</h2><div class=\"education-list\"><div class=\"education-current\"><h3>University of Utah</h3><p>PhD in Computing · In progress</p><p class=\"education-location\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.3\"/></svg><span>Salt Lake City, UT, USA</span></p></div>\n    <div><h3>University of Wisconsin–Madison</h3><p>MS in Information Science <span class=\"education-year\">· 2023</span></p><p class=\"education-location\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.3\"/></svg><span>Madison, WI, USA</span></p></div>\n    <div><h3>East China Normal University</h3><p>BS in Information Management and Systems <span class=\"education-year\">· 2021</span></p><p class=\"education-location\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.3\"/></svg><span>Shanghai, China</span></p></div>\n  </div></section>\n  <section class=\"experience-panel\" id=\"internships\" aria-labelledby=\"internship-title\"><h2 id=\"internship-title\">Internship</h2><div class=\"experience-entries\">\n    <article><div class=\"experience-entry-top\"><h3>Lexical Intelligence</h3><span>2022</span></div><p>Data Scientist Intern</p><p class=\"experience-location\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.3\"/></svg><span>Rockville, MD, USA</span></p></article>\n    <article><div class=\"experience-entry-top\"><h3>Ermenegildo Zegna</h3><span>2019</span></div><p>Data Analytics Intern</p><p class=\"experience-location\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.3\"/></svg><span>Shanghai, China</span></p></article>\n  </div></section>\n  <section class=\"experience-panel\" id=\"teaching\" aria-labelledby=\"teaching-title\"><h2 id=\"teaching-title\">Teaching</h2><div class=\"experience-entries\">\n    <article><div class=\"experience-entry-top\"><h3>CS 6635 · Vis for Scientific Data</h3><span>Spring 2026</span></div><p>Teaching Assistant · University of Utah</p></article>\n    <article><div class=\"experience-entry-top\"><h3>COMP 1010 · Programming for All</h3><span>Fall 2025</span></div><p>Teaching Assistant · University of Utah</p></article>\n  </div></section>\n  <section class=\"experience-panel service-panel\" id=\"service\" aria-labelledby=\"service-title\"><h2 id=\"service-title\">Service</h2><div class=\"service-groups\">\n    <div id=\"reviewing\"><h3>Reviewing</h3><ul><li><span>SIGCHI · 2 papers</span><span>2027</span></li><li><span>PacificVis</span><span>2027</span></li><li><span>The Web Conference</span><span>2023</span></li></ul></div>\n    <div><h3>Community</h3><p>Treasurer · Grad-CS Women</p><p class=\"experience-secondary\">University of Utah · 2024</p></div>\n  </div></section>\n</div></section>"};

function setSiteNavigation(page) {
  document.querySelectorAll('header [data-site-nav]').forEach(a => {
    const active = a.dataset.siteNav === page;
    a.classList.toggle('is-active', active);
    if (active) a.setAttribute('aria-current', 'page');
    else a.removeAttribute('aria-current');
  });
  document.querySelector('header nav').classList.remove('is-open');
  document.querySelector('.site-menu-toggle').setAttribute('aria-expanded', 'false');
}

function renderSitePage(page) {
  currentProject = null;
  isDeck = false;
  document.body.dataset.page = page;
  document.title = (page === 'publications' ? 'Publications' : 'Experiences') + ' — Shiyi He';
  setSiteNavigation(page);
  main.innerHTML = siteSections[page] + '<div class="page-return wrap"><a class="text-link" href="./#work">Explore research projects <span aria-hidden="true">↗</span></a></div>';
  const experienceTarget = page === 'experiences' && ['education','internships','teaching','reviewing','service'].includes(location.hash.slice(1)) ? location.hash.slice(1) : null;
  if (experienceTarget) requestAnimationFrame(() => document.getElementById(experienceTarget)?.scrollIntoView());
  else window.scrollTo(0, 0);
}

document.querySelector('.site-menu-toggle').addEventListener('click', e => {
  const open = document.querySelector('header nav').classList.toggle('is-open');
  e.currentTarget.setAttribute('aria-expanded', String(open));
});
document.querySelector('header nav').addEventListener('click', e => {
  if (e.target.closest('a')) {
    document.querySelector('header nav').classList.remove('is-open');
    document.querySelector('.site-menu-toggle').setAttribute('aria-expanded', 'false');
  }
});

function route(){const path=location.pathname.replace(/\/index\.html$/, '/').replace(/\/$/, '');const staticPage=path.split('/').pop();if(staticPage==='personal'){renderPersonalPage();updateProgress();return;}if(staticPage==='publications'||staticPage==='experiences'){renderSitePage(staticPage);updateProgress();return;}if(location.hash==='#publications'||location.hash==='#experiences'||location.hash==='#personal'){location.href=location.hash.slice(1)+'/';return;}const parts=location.hash.slice(1).split('/');if(parts[0]==='project'){const p=projects.find(x=>x.id===parts[1]);if(!p){renderHome('work');return;}if(currentProject?.id!==p.id)renderProject(p.id);if(parts[2]){const idx=p.sections.findIndex(x=>x.id===parts[2]);if(idx>=0){if(isDeck){deckIndex=idx;updateDeck();}else requestAnimationFrame(()=>document.getElementById('section-'+parts[2]).scrollIntoView());}}}else{renderHome(['work','skills','about'].includes(parts[0])?parts[0]:null);}updateProgress();}
function updateProgress(){const d=document.documentElement;const max=d.scrollHeight-d.clientHeight;document.querySelector('.reading-progress').style.width=(max>0?100*d.scrollTop/max:0)+'%';if(!isDeck&&currentProject){let active=currentProject.sections[0]?.id;document.querySelectorAll('.case-section').forEach(s=>{if(s.getBoundingClientRect().top<220)active=s.id.replace('section-','');});document.querySelectorAll('[data-section]').forEach(a=>a.classList.toggle('active',a.dataset.section===active));}}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.tabIndex=-1;main.focus();main.scrollIntoView();});
window.addEventListener('hashchange',route);window.addEventListener('scroll',updateProgress,{passive:true});document.addEventListener('keydown',e=>{if(!isDeck||!['ArrowRight','ArrowLeft'].includes(e.key)||/BUTTON|INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))return;e.preventDefault();deckIndex+=e.key==='ArrowRight'?1:-1;updateDeck();});route();

